implementation:
#include <stdlib.h>
#include <string.h>

Image* extract_and_process_postscript(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
    ImageInfo *clone_info = CloneImageInfo(image_info);
    if (clone_info == NULL) {
        return image;
    }

    char filename[MagickPathExtent] = {0};
    GetPathComponent(image->filename, NativePath, filename, MagickPathExtent);

    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        DestroyImageInfo(clone_info);
        return image;
    }

    // Ensure PS_Offset and PS_Size are valid
    if (PS_Offset < 0 || PS_Size <= 0) {
        fclose(file);
        DestroyImageInfo(clone_info);
        return image;
    }

    // Write the Postscript data to the file
    size_t bytes_written = 0;
    if (image->blob != NULL && image->blob_size >= (size_t)PS_Offset + (size_t)PS_Size) {
        bytes_written = fwrite((const char*)image->blob + PS_Offset, 1, PS_Size, file);
    }

    fclose(file);

    if (bytes_written != PS_Size) {
        DestroyImageInfo(clone_info);
        return image;
    }

    // Check the file format using magic numbers
    Image *nested_image = ReadImage(clone_info, filename, exception);
    if (nested_image == NULL) {
        DestroyImageInfo(clone_info);
        return image;
    }

    // Replace the original image with the new one
    Image *result = CloneImage(nested_image, 0, 0, MagickTrue, exception);
    if (result != NULL) {
        // Preserve attributes from the original image
        result->depth = image->depth;
        result->colors = image->colors;
        result->montage = image->montage;
        result->page = image->page;
        result->tile = image->tile;
        result->units = image->units;
        result->x_resolution = image->x_resolution;
        result->y_resolution = image->y_resolution;
    }

    // Clean up resources
    DestroyImageInfo(clone_info);
    DestroyImage(nested_image);

    return result;
}
